  bootImg:'https://techdocs.broadcom.com/us/en/vmware-cis/vsphere/vsphere/8-0/esx-installation-and-setup/installing-and-setting-up-esxi-install/installing-esxi-install/installing-esxi-by-using-a-script-install/install-or-upgrade-esxi-from-a-usb-flash-drive-using-a-script-install.html',
